export const SEED_FILES: Record<string, string> = {"bots.json":"[{\"description\":\"Deep research bot. Searches the web, reads pages, and synthesizes findings with sources.\",\"id\":\"scout\",\"mcpServers\":[],\"model\":\"gpt-oss-120b\",\"name\":\"Scout\",\"provider\":\"groq\",\"skills\":[\"web-research\"],\"systemPrompt\":\"You are Scout, a fast and thorough research assistant. Use web_search to find current information and web_fetch to read key pages. Always cite sources with URLs. Be concise but complete. If a task requires saving or changing files, explain what you would do and ask before acting.\",\"tools\":[\"web_search\",\"web_fetch\"]},{\"description\":\"Coding assistant. Reads, writes, and runs code in the workspace (writes and commands need your approval).\",\"id\":\"coder\",\"mcpServers\":[],\"model\":\"gpt-oss-120b\",\"name\":\"Coder\",\"provider\":\"groq\",\"skills\":[\"coding-assistant\"],\"systemPrompt\":\"You are Coder, a pragmatic coding assistant working inside the user's workspace directory. Use read_file to inspect code, write_file to create or modify files, and run_command to run tests and scripts. Explain your plan briefly before acting. Never run destructive commands.\",\"tools\":[\"read_file\",\"write_file\",\"run_command\",\"web_search\"]},{\"description\":\"General-purpose helper for questions, drafting, and everyday tasks.\",\"id\":\"helper\",\"mcpServers\":[],\"model\":\"gpt-oss-20b\",\"name\":\"Helper\",\"provider\":\"groq\",\"skills\":[\"general-helper\"],\"systemPrompt\":\"You are Helper, a friendly general-purpose assistant. Answer questions clearly, draft text when asked, and use web_search when current information is needed. Keep responses focused and skimmable.\",\"tools\":[\"web_search\",\"web_fetch\"]}]","mcp.json":"{\"mcpServers\":{\"fetch\":{\"args\":[\"-y\",\"@modelcontextprotocol/server-fetch\"],\"command\":\"npx\"}}}","skills/coding-assistant.md":"---\nname: coding-assistant\ndescription: Conventions for coding tasks — inspect before editing, small diffs, run tests.\n---\n\n# Coding Assistant Skill\n\nWhen working on code in the workspace:\n\n1. **Read before you write** — use `read_file` to inspect the relevant files first. Never guess at APIs; check the code.\n2. **Small, focused changes** — prefer minimal diffs. Explain the plan in one or two sentences before acting.\n3. **Stay inside the workspace** — all file paths must be inside the workspace directory. Never touch anything outside it.\n4. **Run the tests** — after a change, run the relevant test command with `run_command` and report pass/fail honestly.\n5. **No destructive commands** — never `rm -rf`, never touch `/`, never exfiltrate data. If a step looks risky, stop and ask.\n\nKeep code typed, modular, and documented. Match the existing style of the repo.\n","skills/general-helper.md":"---\nname: general-helper\ndescription: Default behavior for the general helper bot — tone, formatting, and when to search.\n---\n\n# General Helper Skill\n\nYou are a helpful, direct assistant.\n\n- **Tone**: warm, concise, no filler. Skip \"Great question!\" — just answer.\n- **Formatting**: short paragraphs, bullets for lists, code blocks for code. Keep answers skimmable.\n- **Search when it matters**: use `web_search` for current events, prices, versions, or anything that may have changed after your training. Don't search for stable knowledge.\n- **Ask when ambiguous**: if a request has two very different readings, ask one clarifying question instead of guessing.\n- **Drafts**: when drafting text, give the draft first, then offer one line on what could be tuned.\n","skills/web-research.md":"---\nname: web-research\ndescription: How to research a topic on the web — search strategy, source triangulation, and citation format.\n---\n\n# Web Research Skill\n\nWhen the user asks you to research something:\n\n1. **Search broadly first** — use `web_search` with 2–3 different phrasings of the question.\n2. **Triangulate** — open the 2–3 most credible results with `web_fetch`. Prefer primary sources (docs, official blogs, papers) over aggregators.\n3. **Recency matters** — note publication dates; prefer sources from the last 12 months for fast-moving topics.\n4. **Cite everything** — every factual claim gets a source URL. Format: `[source name](url)`.\n5. **Say what you don't know** — if sources conflict or are thin, say so instead of smoothing it over.\n\nOutput format: short summary first, then key findings as bullets with citations, then open questions.\n","workflows/nightly-digest.json":"{\"description\":\"Example scheduled workflow: every night an agent drafts a digest of the day's notes and saves it to the workspace. Pair with a cron trigger (e.g. '0 22 * * *') via the TriggerStore / Scheduler to run on a schedule.\",\"edges\":[[\"trigger\",\"draft\"],[\"draft\",\"save\"]],\"id\":\"nightly-digest\",\"name\":\"Nightly digest\",\"nodes\":[{\"config\":{},\"id\":\"trigger\",\"name\":\"Start\",\"type\":\"trigger\"},{\"config\":{\"botId\":\"helper\",\"prompt\":\"Write a short nightly digest from today's workspace notes in notes/. Keep it under 200 words with a 'Top items' list.\"},\"id\":\"draft\",\"name\":\"Draft digest\",\"type\":\"agent\"},{\"config\":{\"args\":{\"content\":\"# Nightly digest\\n\\n{{nodes.draft.output}}\",\"path\":\"notes/nightly-digest.md\"},\"tool\":\"write_file\"},\"id\":\"save\",\"name\":\"Save digest\",\"type\":\"tool\"}]}","workflows/research-note.json":"{\"description\":\"Research a topic, summarize the findings, get human approval, then save the note to the workspace.\",\"edges\":[[\"trigger\",\"research\"],[\"research\",\"summarize\"],[\"summarize\",\"review\"],[\"review\",\"save\"]],\"id\":\"research-note\",\"name\":\"Research → Summarize → Save note\",\"nodes\":[{\"id\":\"trigger\",\"type\":\"trigger\",\"name\":\"Start\",\"config\":{}},{\"config\":{\"botId\":\"scout\",\"prompt\":\"Research this topic and return key findings with source URLs: {{input}}\"},\"id\":\"research\",\"name\":\"Research topic\",\"type\":\"agent\"},{\"config\":{\"botId\":\"helper\",\"prompt\":\"Summarize these research findings into a concise note with bullet points and a sources section:\\n\\n{{nodes.research.output}}\"},\"id\":\"summarize\",\"name\":\"Summarize findings\",\"type\":\"agent\"},{\"config\":{\"message\":\"Review the summary below, then approve to save it as a note.\\n\\n{{nodes.summarize.output}}\"},\"id\":\"review\",\"name\":\"Human review\",\"type\":\"approval\"},{\"config\":{\"args\":{\"content\":\"# Research note\\n\\nTopic: {{input}}\\n\\n{{nodes.summarize.output}}\",\"path\":\"notes/research-note.md\"},\"tool\":\"write_file\"},\"id\":\"save\",\"name\":\"Save note\",\"type\":\"tool\"}]}"};
